-- M05 owns adjustment review, after-sales and debt records. M02-M04 own all base tables.
BEGIN;
DO $$ BEGIN
 IF to_regclass('runrun_v2.v2_orders') IS NULL OR to_regclass('runrun_v2.payment_orders') IS NULL OR to_regclass('runrun_v2.fulfillment_completion_blocks') IS NULL THEN RAISE EXCEPTION 'M05 requires M02-M04 migrations'; END IF;
END $$;
CREATE TABLE runrun_v2.order_adjustments (
 id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES runrun_v2.v2_orders(id), requested_by BIGINT NOT NULL REFERENCES runrun_v2.app_users(id), spec_proof_id BIGINT,
 from_service_type TEXT NOT NULL, to_service_type TEXT NOT NULL, delta_cents BIGINT NOT NULL CHECK(delta_cents<>0),
 status TEXT NOT NULL DEFAULT 'PENDING_REVIEW' CHECK(status IN ('PENDING_REVIEW','PENDING_PAYMENT','PENDING_REFUND','COMPLETED','REJECTED','CLOSED_ORIGINAL_PRICE','CANCELLED')),
 assigned_admin_id BIGINT REFERENCES runrun_v2.app_users(id), requested_at TIMESTAMPTZ NOT NULL DEFAULT now(), remind_at TIMESTAMPTZ, escalate_at TIMESTAMPTZ, decided_at TIMESTAMPTZ, pay_deadline TIMESTAMPTZ, resolved_at TIMESTAMPTZ, decision_reason TEXT);
CREATE UNIQUE INDEX order_adjustments_one_open ON runrun_v2.order_adjustments(order_id) WHERE status IN ('PENDING_REVIEW','PENDING_PAYMENT','PENDING_REFUND');
CREATE TABLE runrun_v2.after_sales_cases (
 id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES runrun_v2.v2_orders(id), opened_by BIGINT NOT NULL REFERENCES runrun_v2.app_users(id), assigned_admin_id BIGINT REFERENCES runrun_v2.app_users(id), kind TEXT NOT NULL, reason TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','INVESTIGATING','RESOLVED')), requested_cents BIGINT CHECK(requested_cents IS NULL OR requested_cents>=0), resolution JSONB, resolved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX after_sales_order_status ON runrun_v2.after_sales_cases(order_id,status);
CREATE TABLE runrun_v2.debts (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES runrun_v2.v2_orders(id), debtor_id BIGINT NOT NULL REFERENCES runrun_v2.app_users(id), source_type TEXT NOT NULL, source_id TEXT NOT NULL, principal_cents BIGINT NOT NULL CHECK(principal_cents>0), outstanding_cents BIGINT NOT NULL CHECK(outstanding_cents>=0), status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','SETTLED','WAIVED','RECOVERY_STOPPED')), reason TEXT NOT NULL, closed_at TIMESTAMPTZ);
CREATE TABLE runrun_v2.m05_order_events (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES runrun_v2.v2_orders(id), actor_id BIGINT REFERENCES runrun_v2.app_users(id), event_type TEXT NOT NULL, request_id TEXT NOT NULL, payload JSONB NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(payload)='object'), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(order_id,event_type,request_id));
CREATE OR REPLACE FUNCTION runrun_v2.request_adjustment(p_order_id BIGINT,p_actor BIGINT,p_to_type TEXT,p_delta BIGINT,p_reason TEXT,p_proof BIGINT DEFAULT NULL) RETURNS BIGINT LANGUAGE plpgsql AS $$ DECLARE o runrun_v2.v2_orders; a BIGINT; BEGIN SELECT * INTO o FROM runrun_v2.v2_orders WHERE id=p_order_id FOR UPDATE; IF NOT FOUND OR o.status IN ('COMPLETED','CANCELLED','EXCEPTION') THEN RAISE EXCEPTION 'ORDER_STATE_CONFLICT'; END IF; IF EXISTS(SELECT 1 FROM runrun_v2.order_adjustments WHERE order_id=p_order_id AND status IN ('PENDING_REVIEW','PENDING_PAYMENT','PENDING_REFUND')) THEN RAISE EXCEPTION 'ADJUSTMENT_ALREADY_OPEN'; END IF; INSERT INTO runrun_v2.order_adjustments(order_id,requested_by,spec_proof_id,from_service_type,to_service_type,delta_cents,decision_reason) VALUES(p_order_id,p_actor,p_proof,o.service_type,p_to_type,p_delta,p_reason) RETURNING id INTO a; INSERT INTO runrun_v2.fulfillment_completion_blocks(order_id,source_type,source_id) VALUES(p_order_id,'ADJUSTMENT',a::text); UPDATE runrun_v2.v2_orders SET version=version+1 WHERE id=p_order_id; RETURN a; END $$;
CREATE OR REPLACE FUNCTION runrun_v2.decide_adjustment(p_id BIGINT,p_admin BIGINT,p_decision TEXT,p_reason TEXT) RETURNS VOID LANGUAGE plpgsql AS $$ DECLARE a runrun_v2.order_adjustments; BEGIN SELECT * INTO a FROM runrun_v2.order_adjustments WHERE id=p_id FOR UPDATE; IF NOT FOUND OR a.status<>'PENDING_REVIEW' THEN RAISE EXCEPTION 'ORDER_STATE_CONFLICT'; END IF; PERFORM 1 FROM runrun_v2.v2_orders WHERE id=a.order_id FOR UPDATE; IF p_decision IN ('REJECT','CLOSE_ORIGINAL_PRICE') THEN UPDATE runrun_v2.order_adjustments SET status=CASE WHEN p_decision='REJECT' THEN 'REJECTED' ELSE 'CLOSED_ORIGINAL_PRICE' END,decided_at=now(),resolved_at=now(),decision_reason=p_reason WHERE id=a.id; DELETE FROM runrun_v2.fulfillment_completion_blocks WHERE order_id=a.order_id AND source_type='ADJUSTMENT' AND source_id=a.id::text; ELSIF p_decision='APPROVE' THEN INSERT INTO runrun_v2.payment_adjustments(id,order_id,delta_cents,status,approved_by,reason,approved_at) VALUES(a.id,a.order_id,a.delta_cents,CASE WHEN a.delta_cents>0 THEN 'PENDING_SUPPLEMENT' ELSE 'PENDING_REFUND' END,p_admin,p_reason,now()); UPDATE runrun_v2.order_adjustments SET status=CASE WHEN a.delta_cents>0 THEN 'PENDING_PAYMENT' ELSE 'PENDING_REFUND' END,decided_at=now(),pay_deadline=CASE WHEN a.delta_cents>0 THEN now()+interval '15 minutes' ELSE NULL END,decision_reason=p_reason WHERE id=a.id; ELSE RAISE EXCEPTION 'ORDER_STATE_CONFLICT'; END IF; UPDATE runrun_v2.v2_orders SET version=version+1,confirm_started_at=NULL,confirm_deadline=NULL WHERE id=a.order_id; END $$;
CREATE OR REPLACE FUNCTION runrun_v2.resolve_adjustment(p_id BIGINT,p_success BOOLEAN) RETURNS VOID LANGUAGE plpgsql AS $$ DECLARE a runrun_v2.order_adjustments; BEGIN SELECT * INTO a FROM runrun_v2.order_adjustments WHERE id=p_id FOR UPDATE; IF NOT FOUND OR a.status NOT IN ('PENDING_PAYMENT','PENDING_REFUND') THEN RAISE EXCEPTION 'ORDER_STATE_CONFLICT'; END IF; IF p_success THEN UPDATE runrun_v2.payment_adjustments SET status='COMPLETED',resolved_at=now(),version=version+1 WHERE id=a.id; UPDATE runrun_v2.order_adjustments SET status='COMPLETED',resolved_at=now() WHERE id=a.id; DELETE FROM runrun_v2.fulfillment_completion_blocks WHERE order_id=a.order_id AND source_type='ADJUSTMENT' AND source_id=a.id::text; UPDATE runrun_v2.v2_orders SET effective_fee_cents=effective_fee_cents+a.delta_cents,confirm_started_at=now(),confirm_deadline=now()+interval '10 minutes',version=version+1 WHERE id=a.order_id; END IF; END $$;
CREATE OR REPLACE FUNCTION runrun_v2.open_after_sales(p_order_id BIGINT,p_actor BIGINT,p_kind TEXT,p_reason TEXT,p_requested BIGINT DEFAULT NULL) RETURNS BIGINT LANGUAGE plpgsql AS $$ DECLARE c BIGINT; BEGIN PERFORM 1 FROM runrun_v2.v2_orders WHERE id=p_order_id FOR UPDATE; INSERT INTO runrun_v2.after_sales_cases(order_id,opened_by,kind,reason,requested_cents) VALUES(p_order_id,p_actor,p_kind,p_reason,p_requested) RETURNING id INTO c; INSERT INTO runrun_v2.fulfillment_completion_blocks(order_id,source_type,source_id) VALUES(p_order_id,'AFTER_SALES',c::text); UPDATE runrun_v2.v2_orders SET status=CASE WHEN status='DELIVERED_PENDING_CONFIRMATION' THEN 'EXCEPTION' ELSE status END,version=version+1 WHERE id=p_order_id; RETURN c; END $$;
CREATE OR REPLACE FUNCTION runrun_v2.resolve_after_sales(p_case BIGINT,p_admin BIGINT,p_resolution JSONB) RETURNS VOID LANGUAGE plpgsql AS $$ DECLARE c runrun_v2.after_sales_cases; BEGIN SELECT * INTO c FROM runrun_v2.after_sales_cases WHERE id=p_case FOR UPDATE; IF NOT FOUND OR c.status='RESOLVED' THEN RAISE EXCEPTION 'ORDER_STATE_CONFLICT'; END IF; PERFORM 1 FROM runrun_v2.v2_orders WHERE id=c.order_id FOR UPDATE; UPDATE runrun_v2.after_sales_cases SET status='RESOLVED',resolution=p_resolution,resolved_at=now(),assigned_admin_id=p_admin WHERE id=p_case; DELETE FROM runrun_v2.fulfillment_completion_blocks WHERE order_id=c.order_id AND source_type='AFTER_SALES' AND source_id=p_case::text; UPDATE runrun_v2.v2_orders SET status=CASE WHEN status='EXCEPTION' THEN 'DELIVERED_PENDING_CONFIRMATION' ELSE status END,confirm_started_at=now(),confirm_deadline=now()+interval '10 minutes',version=version+1 WHERE id=c.order_id; END $$;
CREATE OR REPLACE FUNCTION runrun_v2.complete_order(p_order_id BIGINT,p_actor BIGINT,p_request TEXT) RETURNS VOID LANGUAGE plpgsql AS $$ BEGIN PERFORM 1 FROM runrun_v2.v2_orders WHERE id=p_order_id FOR UPDATE; IF EXISTS(SELECT 1 FROM runrun_v2.fulfillment_completion_blocks WHERE order_id=p_order_id) THEN RAISE EXCEPTION 'ORDER_COMPLETION_BLOCKED'; END IF; UPDATE runrun_v2.v2_orders SET status='COMPLETED',completed_at=now(),version=version+1 WHERE id=p_order_id AND status='DELIVERED_PENDING_CONFIRMATION'; IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_STATE_CONFLICT'; END IF; INSERT INTO runrun_v2.m05_order_events(order_id,actor_id,event_type,request_id) VALUES(p_order_id,p_actor,'ORDER_COMPLETED',p_request) ON CONFLICT DO NOTHING; END $$;
CREATE OR REPLACE FUNCTION runrun_v2.proof_access_allowed(p_order_id BIGINT,p_kind TEXT) RETURNS BOOLEAN LANGUAGE sql STABLE AS $$ SELECT NOT (p_kind IN ('DELIVERY','LOCATION') AND EXISTS(SELECT 1 FROM runrun_v2.order_adjustments WHERE order_id=p_order_id AND status='PENDING_PAYMENT')); $$;
COMMIT;
